contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint firstMin, uint secondMin) public payable {
        c.SetMinSum(firstMin); if (__ESBMC_reverted()) return;
        require(c.MinSum() == firstMin, "pre-init SetMinSum failed");

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetMinSum(secondMin); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(secondReverted && c.MinSum() == firstMin);
    }
}

