// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 firstMin, uint256 secondMin) internal {
        try c.SetMinSum(firstMin) {} catch { return; }
        firstMin = c.MinSum();
        try c.Initialized() {} catch { return; }
        bool secondReverted;
        try c.SetMinSum(secondMin) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assertTrue(secondReverted && c.MinSum() == firstMin);
    }

    function testFuzz_run(uint256 firstMin, uint256 secondMin) public {
        _run(firstMin, secondMin);
    }

    receive() external payable {}
}
